        /* velocity depth (control rate): gain = 32768 - depth + velocity*depth/32768. */
        op3_velamp_cv_x[v] = 32768 - op3_velamp_depth[voice_part[v]] + p1_q15_mul(voice_velocity[v], op3_velamp_depth[voice_part[v]]);
