                route_mod2_x = p1_q15_mul(d1_out_x, 32767) * 2;
                route_mod3_x = p1_q15_mul(d2_out_x, 32767) * 2;
                route_mod4_x = p1_q15_mul(d3_out_x, 32767) * 2;
                route_car_x = p1_q15_mul(d4_out_x, 32767);
